import { path } from '@servicenow/sdk-build-core'
import { createTestContext } from '../test-utils'

describe('HTML Tests', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })

    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())

    test('Basic usage', async () => {
        const project = ctx.createProject()

        project.addFile({
            path: 'client/index.html',
            content: `<example></example>`,
        })

        const fluentFile = project.addFile({
            path: 'fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'
import html from '../client/index.html'

Record({
    $id: Now.ID['123'],
    table: 'example',
    data: { htmlProp: html }
})
`,
        })

        const diagnostics = await fluentFile.getDiagnostics()
        expect(diagnostics.map((d) => d.message)).toHaveLength(0)

        const records = await fluentFile.getRecords()
        const [record] = records.query()

        expect(record).toBeDefined()
        expect(record.getTable()).toBe('example')
        expect(record.get('htmlProp').getValue()).toMatchInlineSnapshot(`
"<!-- @fluent-import-html WARNING: This file was imported from the output of a static build. Modifications of any kind are likely to result in unintended behavior. In most cases, you should edit the source file of the HTML imported below. If you are absolutely certain you want to take control of this HTML, you can remove this comment to prevent the SDK from regenerating it. However, you will then be responsible for the management of this HTML in your Fluent file. -->
<example></example>"
`)
    })
    test('absolute path diagnostic', async () => {
        const project = ctx.createProject()

        const fluentFile = project.addFile({
            path: 'fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'
import html from '/client/index.html'

Record({
    $id: Now.ID['123'],
    table: 'example',
    data: { htmlProp: html }
})
`,
        })

        const diagnostics = await fluentFile.getDiagnostics()
        expect(diagnostics.map((d) => d.message)).toEqual(['import must be a relative path'])
    })

    test('file not found diagnostic', async () => {
        const project = ctx.createProject()

        const fluentFile = project.addFile({
            path: 'fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'
import html from '../client/missing.html'

Record({
    $id: Now.ID['123'],
    table: 'example',
    data: { htmlProp: html }
})
`,
        })

        const diagnostics = await fluentFile.getDiagnostics()
        expect(
            diagnostics
                .map((d) => d.message)
                .some((msg) => msg.startsWith('failed to add HTML file: No file found at path:'))
        ).toBe(true)
    })

    test('outside project diagnostic', async () => {
        const project = ctx.createProject()

        const fluentFile = project.addFile({
            path: 'index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'
import html from '../client/index.html'

Record({
    $id: Now.ID['123'],
    table: 'example',
    data: { htmlProp: html }
})
`,
        })

        const diagnostics = await fluentFile.getDiagnostics()
        expect(diagnostics.map((d) => d.message)).toEqual(['import not within project: ../client/index.html'])
    })
    test('transform XML into Fluent with import directive comment results in no changes', async () => {
        const project = ctx.createProject()

        const recordId = project.registerExplicitId('example', '123')

        project.addFile({
            path: 'client/index.html',
            content: `<example></example>`,
        })

        project.addFile({
            path: 'fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'
import html from '../client/index.html'

Record({
    $id: Now.ID['123'],
    table: 'example',
    data: { htmlProp: html }
})
`,
        })

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `<?xml version="1.0"?>
<record_update>
  <example action="INSERT_OR_UPDATE">
    <sys_id>${recordId}</sys_id>
    <htmlProp><![CDATA[
<!-- @fluent-import-html -->
<example></example>
]]></htmlProp>
  </example>
</record_update>`,
        })
        expect(changedFiles).toHaveLength(0)
    })
    test('transform XML into Fluent without import directive comment replaces with string', async () => {
        const project = ctx.createProject()

        const html = `<example></example>`
        project.addFile({
            path: 'client/index.html',
            content: html,
        })

        const recordId = project.registerExplicitId('example', '123')

        project.addFile({
            path: 'client/index.html',
            content: `<example></example>`,
        })

        project.addFile({
            path: 'fluent/index.now.ts',
            content: `import { Record } from '@servicenow/sdk/core'
import html from '../client/index.html'

Record({
    $id: Now.ID['123'],
    table: 'example',
    data: { htmlProp: html }
})
`,
        })

        const { changedFiles } = await project.transform({
            path: 'changes.xml',
            content: `<?xml version="1.0"?>
<record_update>
  <example action="INSERT_OR_UPDATE">
    <sys_id>${recordId}</sys_id>
    <htmlProp><![CDATA[
<example>modified on instance</example>
]]></htmlProp>
  </example>
</record_update>`,
        })
        expect(changedFiles).toHaveLength(1)
        expect(changedFiles[0].getPath()).toMatch(/fluent\/index\.now\.ts$/)
        expect(changedFiles[0].getContent()).toMatchInlineSnapshot(`
"import { Record } from '@servicenow/sdk/core'

Record({
    $id: Now.ID['123'],
    table: 'example',
    data: {
        htmlProp: \`
<example>modified on instance</example>
\`,
    },
})
"
`)
    })
})
